/* 称重单子系统 · 两个页面共用的样式。内网部署:不引用任何外部字体或 CDN。 */
:root{
  --ground:#ECEEEF;      /* 地磅房的水泥灰:页面底色 */
  --paper:#FFFFFF;       /* 单据纸 */
  --ink:#1E2329;
  --ink-2:#5B6470;
  --ink-3:#8A929C;
  --line:#D5D9DD;
  --line-2:#E8EBED;
  --brand:#1F4E8C;       /* 票据蓝,沿用 0.1 版 */
  --brand-2:#173D6E;
  --brand-weak:#E6EDF7;
  --pass:#1F7A43;  --pass-bg:#E4F2E8;
  --attn:#7A5000;  --attn-bg:#FFF4D1; --attn-edge:#E8A800;   /* 安全黄:要人看一眼 */
  --fail:#B3261E;  --fail-bg:#FBE8E6;
  --rev:#3A4F9A;   --rev-bg:#E9ECF8;
  --readout-bg:#1C1F22; --readout-fg:#FFB547; --readout-dim:#5A4A2E;
  --num:"SF Mono","Cascadia Mono","Roboto Mono",Consolas,Menlo,monospace;
  --ui:-apple-system,BlinkMacSystemFont,"PingFang SC","Hiragino Sans GB","Microsoft YaHei","Noto Sans CJK SC",sans-serif;
  --r:4px;
}
*{box-sizing:border-box}
[hidden]{display:none!important}   /* 带 display 的类不许盖过 hidden */
html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--ground);color:var(--ink);font:15px/1.6 var(--ui)}
a{color:var(--brand)}
button,input,select{font:inherit;color:inherit}
:focus-visible{outline:3px solid var(--attn-edge);outline-offset:2px}
.num{font-family:var(--num);font-variant-numeric:tabular-nums}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}

/* 顶栏 */
.bar{background:var(--paper);border-bottom:1px solid var(--line)}
.bar-in{display:flex;align-items:center;gap:16px;padding:12px 16px;margin:0 auto}
.bar h1{margin:0;font-size:18px;font-weight:650;letter-spacing:.02em}
.bar h1 small{font-size:13px;font-weight:400;color:var(--ink-2);margin-left:8px;letter-spacing:0}
.bar nav{margin-left:auto;display:flex;gap:4px}
.bar nav a{padding:6px 10px;border-radius:var(--r);text-decoration:none;color:var(--ink-2);font-size:14px}
.bar nav a[aria-current="page"]{color:var(--brand);background:var(--brand-weak);font-weight:600}

/* 按钮 */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:1px solid transparent;
  border-radius:var(--r);padding:8px 16px;font-size:14px;cursor:pointer;text-decoration:none;
  background:var(--brand);color:#fff;min-height:38px}
.btn:hover{background:var(--brand-2)}
.btn:disabled{background:#AEB6C0;border-color:#AEB6C0;cursor:not-allowed}
.btn.ghost{background:var(--paper);color:var(--brand);border-color:#B9C6D8}
.btn.ghost:hover{background:var(--brand-weak)}
.btn.quiet{background:transparent;color:var(--ink-2);border-color:transparent}
.btn.quiet:hover{background:var(--line-2);color:var(--ink)}
.btn.ghost:disabled,.btn.quiet:disabled{background:var(--paper);color:var(--ink-3);border-color:var(--line-2);cursor:not-allowed}

/* 状态标记:颜色之外永远配文字 */
.tag{display:inline-block;font-size:12px;line-height:20px;padding:0 8px;border-radius:10px;white-space:nowrap;font-weight:600}
.tag.auto_ok{color:var(--pass);background:var(--pass-bg)}
.tag.needs_review{color:var(--attn);background:var(--attn-bg)}
.tag.failed{color:var(--fail);background:var(--fail-bg)}
.tag.reviewed{color:var(--rev);background:var(--rev-bg)}

/* 地磅仪表读数:整套界面唯一的「重」元素 */
.readout{display:flex;align-items:baseline;justify-content:flex-end;gap:6px;background:var(--readout-bg);
  color:var(--readout-fg);border-radius:var(--r);padding:8px 14px;font-family:var(--num);
  font-variant-numeric:tabular-nums;box-shadow:inset 0 0 0 1px #000,inset 0 2px 10px rgba(0,0,0,.6)}
.readout .v{font-size:34px;line-height:1.1;letter-spacing:.06em;text-shadow:0 0 12px rgba(255,181,71,.35)}
.readout .u{font-size:14px;color:#C9965A}
.readout .k{margin-right:auto;align-self:center;font-family:var(--ui);font-size:13px;color:#A99070}
.readout.bad .v{color:#FF7A6E;text-shadow:0 0 12px rgba(255,122,110,.35)}
.readout.none .v{color:var(--readout-dim);text-shadow:none}

/* 校验警告 */
.warn-list{margin:0;padding:0;list-style:none}
.warn-list li{position:relative;padding:6px 10px 6px 12px;margin:4px 0;font-size:13px;line-height:1.5;
  background:var(--attn-bg);color:var(--attn);border-left:3px solid var(--attn-edge);border-radius:0 var(--r) var(--r) 0}
.warn-list li.fail{background:var(--fail-bg);color:var(--fail);border-left-color:var(--fail)}

/* 横幅 */
.banner{padding:10px 14px;border-radius:var(--r);font-size:14px;margin:0 0 12px}
.banner.fail{background:var(--fail-bg);color:var(--fail)}
.banner.attn{background:var(--attn-bg);color:var(--attn)}

@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}

/* 称重单采集页的离线外壳:信号差、甚至没网的时候,页面照样能打开、能拍照,照片进手机上的待传箱。
   只缓存页面和样式,不缓存任何接口和图片(台账数据不留在手机上)。页面先走网络,网络不通才用缓存,所以升级后不会卡在旧版。 */
const BASE_PATH = "/pv/INDEPENDENT-1/__commit/bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
const CACHE_PREFIX = "weighbill-shell:" + BASE_PATH + ":";
const CACHE = CACHE_PREFIX + "v3";
const SHELL = [BASE_PATH + "/static/app.css"];

self.addEventListener("install", e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(SHELL)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k.startsWith(CACHE_PREFIX) && k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});

self.addEventListener("fetch", e => {
  const req = e.request;
  if (req.method !== "GET") return;                                  // 上传等一律不管
  const url = new URL(req.url);
  if (url.origin !== location.origin) return;
  const isPage = req.mode === "navigate" && (url.pathname === BASE_PATH + "/" || url.pathname.startsWith(BASE_PATH + "/c/"));
  const isShell = url.pathname.startsWith(BASE_PATH + "/static/") && !url.pathname.endsWith("sw.js");
  if (!isPage && !isShell) return;                                   // 接口、图片、台账页:不缓存
  e.respondWith(
    fetch(req).then(res => {
      if (res.ok) { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); }
      return res;
    }).catch(() => caches.match(req).then(hit => hit || caches.match(BASE_PATH + "/static/app.css").then(() =>
      new Response("<meta charset=utf-8><p style='font:16px sans-serif;padding:20px'>没有网络,而且这台手机还没打开过采集页。有信号时先打开一次,以后没网也能拍。</p>",
                   {headers: {"Content-Type": "text/html; charset=utf-8"}}))))
  );
});
